        ('web-development', 'Angular Learning Resources', 'Explore Angular components, templates, dependency injection, routing, and modern application patterns.', 'Angular', 'https://angular.dev/overview', 'Beginner', 'documentation', array['Angular', 'TypeScript', 'JavaScript'], array['Build standalone components', 'Configure routes', 'Connect services to templates']),
