        ('web-development', 'Tailwind CSS Installation', 'Set up Tailwind CSS and learn utility-first styling, responsive variants, and component patterns.', 'Tailwind Labs', 'https://tailwindcss.com/docs/installation', 'Beginner', 'documentation', array['Tailwind CSS', 'CSS', 'HTML'], array['Configure Tailwind CSS', 'Apply responsive utilities', 'Compose reusable styles']),
