        ('databases', 'Redis University', 'Explore Redis data structures, keys, caching, messaging, and common application patterns.', 'Redis', 'https://university.redis.io/', 'Intermediate', 'course', array['Redis', 'NoSQL'], array['Choose Redis data structures', 'Use Redis for caching', 'Implement basic pub-sub']),
        ('developer-tools', 'GitHub Actions Quickstart', 'Automate build and test workflows with GitHub Actions events, jobs, runners, and actions.', 'GitHub', 'https://docs.github.com/en/actions/writing-workflows/quickstart', 'Beginner', 'tutorial', array['GitHub Actions', 'GitHub', 'CI/CD'], array['Create a workflow', 'Run tests automatically', 'Inspect workflow results']),
        ('developer-tools', 'Kubernetes Basics', 'Learn Pods, Deployments, Services, kubectl, and the fundamentals of container orchestration.', 'Kubernetes', 'https://kubernetes.io/docs/tutorials/kubernetes-basics/', 'Intermediate', 'tutorial', array['Kubernetes', 'Docker', 'Linux'], array['Deploy a containerized application', 'Explore Pods and Services', 'Scale an application']),
        ('developer-tools', 'Linux Journey', 'Practice Linux commands, filesystems, processes, permissions, networking, and system administration basics.', 'Linux Journey', 'https://linuxjourney.com/', 'Beginner', 'tutorial', array['Linux'], array['Navigate the shell', 'Manage files and permissions', 'Understand processes']),
        ('testing', 'Playwright Getting Started', 'Set up Playwright and write browser tests for navigation, interactions, assertions, and debugging.', 'Microsoft', 'https://playwright.dev/docs/intro', 'Beginner', 'documentation', array['Testing', 'JavaScript', 'TypeScript'], array['Write browser tests', 'Interact with web elements', 'Debug Playwright failures']),
        ('testing', 'OWASP Web Security Testing Guide', 'Learn structured web application security testing concepts, threat categories, and verification techniques.', 'OWASP', 'https://owasp.org/www-project-web-security-testing-guide/', 'Advanced', 'documentation', array['Cybersecurity', 'Testing'], array['Identify security testing areas', 'Use repeatable verification steps', 'Document security findings']),
        ('data-structures-algorithms', 'Introduction to Algorithms', 'Study algorithm analysis, sorting, graphs, dynamic programming, and fundamental data structures through MIT lecture notes and videos.', 'MIT OpenCourseWare', 'https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/', 'Intermediate', 'course', array['DSA', 'Algorithms', 'Data Structures'], array['Analyze asymptotic complexity', 'Implement standard data structures', 'Solve graph and dynamic-programming problems']),
        ('data-structures-algorithms', 'Python Algorithms and Data Structures', 'Practice Python implementations of arrays, linked lists, trees, graphs, sorting, searching, and graph algorithms.', 'OpenDSA', 'https://opendsa-server.cs.vt.edu/OpenDSA/Books/PythonDSA/html/', 'Intermediate', 'course', array['DSA', 'Algorithms', 'Python', 'Data Structures'], array['Implement core data structures', 'Compare sorting and searching algorithms', 'Trace common algorithm strategies']),
        ('data-structures-algorithms', 'VisuAlgo', 'Visualize common data structures and algorithms for arrays, trees, heaps, graphs, and dynamic programming.', 'VisuAlgo', 'https://visualgo.net/en', 'All levels', 'practice', array['DSA', 'Algorithms', 'Data Structures'], array['Observe algorithm execution', 'Compare traversal behavior', 'Develop intuition for complexity']),
        ('data-structures-algorithms', 'LeetCode Explore: Data Structures', 'Practice interview-oriented problems for arrays, linked lists, stacks, queues, trees, and hash tables.', 'LeetCode', 'https://leetcode.com/explore/learn/card/data-structure-tree/', 'Intermediate', 'practice', array['DSA', 'Data Structures', 'Problem Solving'], array['Recognize reusable patterns', 'Implement data structure operations', 'Explain solution complexity']),
        ('system-design', 'Well-Architected Framework', 'Learn reliability, security, performance efficiency, cost optimization, and operational excellence for cloud systems.', 'Amazon Web Services', 'https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html', 'Advanced', 'documentation', array['System Design', 'Cloud', 'Architecture'], array['Evaluate architectural trade-offs', 'Design for reliability', 'Apply security and performance pillars']),
        ('system-design', 'Azure Application Architecture Fundamentals', 'Study cloud application patterns, scalability, availability, resiliency, microservices, and data architecture.', 'Microsoft', 'https://learn.microsoft.com/en-us/azure/architecture/guide/', 'Advanced', 'documentation', array['System Design', 'Cloud', 'Architecture', 'Microservices'], array['Choose application patterns', 'Design scalable services', 'Plan resilient deployments']),
        ('system-design', 'Google SRE Handbook', 'Learn service-level objectives, reliability engineering, incident response, automation, and operational practices.', 'Google', 'https://sre.google/sre-book/table-of-contents/', 'Advanced', 'course', array['System Design', 'DevOps', 'Reliability', 'Cloud'], array['Define service objectives', 'Understand error budgets', 'Apply reliability practices']),
        ('system-design', 'API Gateway Microservice Patterns', 'Explore API gateway responsibilities and trade-offs in distributed microservice architectures.', 'Microsoft', 'https://learn.microsoft.com/en-us/azure/architecture/microservices/design/gateway', 'Intermediate', 'documentation', array['System Design', 'Microservices', 'REST APIs', 'Architecture'], array['Design an API gateway', 'Separate edge and domain concerns', 'Evaluate routing and security trade-offs']),
        ('system-design', 'Nginx Load Balancing', 'Learn how load balancing distributes traffic across application servers and improves availability.', 'F5 NGINX', 'https://docs.nginx.com/nginx/admin-guide/load-balancer/http-load-balancer/', 'Intermediate', 'tutorial', array['System Design', 'Load Balancing', 'Networking'], array['Configure upstream servers', 'Compare balancing methods', 'Improve availability with health-aware routing']),
        ('data-science', 'Pandas Getting Started', 'Learn tabular data loading, cleaning, filtering, transformation, grouping, and analysis with pandas.', 'pandas', 'https://pandas.pydata.org/docs/getting_started/index.html', 'Beginner', 'documentation', array['Data Science', 'Python', 'Pandas'], array['Explore tabular datasets', 'Clean and transform records', 'Compute grouped summaries']),
        ('data-science', 'NumPy Quickstart', 'Practice arrays, indexing, broadcasting, vectorized operations, and numerical computation with NumPy.', 'NumPy', 'https://numpy.org/doc/stable/user/quickstart.html', 'Beginner', 'tutorial', array['Data Science', 'Python', 'NumPy'], array['Manipulate multidimensional arrays', 'Apply vectorized operations', 'Use broadcasting correctly']),
        ('data-science', 'Data Analysis with Python', 'Complete guided data-analysis lessons covering data collection, cleaning, visualization, and interpretation.', 'freeCodeCamp', 'https://www.freecodecamp.org/learn/data-analysis-with-python/', 'Beginner', 'course', array['Data Science', 'Python', 'Pandas', 'Data Visualization'], array['Clean real-world data', 'Create data visualizations', 'Perform exploratory analysis']),
        ('data-science', 'Statistics for Data Science', 'Build a foundation in probability, distributions, sampling, estimation, and statistical testing.', 'OpenStax', 'https://openstax.org/details/books/introductory-statistics-2e', 'Beginner', 'course', array['Data Science', 'Statistics', 'Probability'], array['Interpret descriptive statistics', 'Explain probability distributions', 'Perform basic inference']),
        ('data-science', 'Scikit-learn Getting Started', 'Understand estimators, preprocessing, model selection, pipelines, and evaluation for machine-learning workflows.', 'scikit-learn', 'https://scikit-learn.org/stable/getting_started.html', 'Intermediate', 'documentation', array['Data Science', 'Machine Learning', 'Scikit-learn', 'Python'], array['Prepare features', 'Fit baseline models', 'Evaluate predictions']),
        ('artificial-intelligence', 'AI for Everyone', 'Learn the practical vocabulary, project lifecycle, organizational impact, and limitations of AI systems.', 'DeepLearning.AI', 'https://www.deeplearning.ai/courses/ai-for-everyone/', 'Beginner', 'course', array['Artificial Intelligence', 'AI', 'Communication'], array['Describe common AI applications', 'Understand an AI project lifecycle', 'Discuss ethical and organizational considerations']),
        ('artificial-intelligence', 'Google Responsible AI Resources', 'Study fairness, privacy, transparency, safety, and human-centered principles for AI systems.', 'Google', 'https://www.google.com/intl/en_uk/about/responsible-ai/', 'All levels', 'documentation', array['Artificial Intelligence', 'Responsible AI', 'Ethics'], array['Identify common AI risks', 'Use responsible design principles', 'Evaluate fairness and transparency']),
        ('artificial-intelligence', 'Hugging Face NLP Course', 'Learn transformer language models, tokenization, datasets, training, and evaluation using an open ecosystem.', 'Hugging Face', 'https://huggingface.co/learn/nlp-course/', 'Intermediate', 'course', array['Artificial Intelligence', 'NLP', 'Transformers', 'Python'], array['Tokenize text', 'Fine-tune a transformer', 'Evaluate language-model outputs']),
        ('artificial-intelligence', 'Prompt Engineering Guide', 'Study prompt design patterns, retrieval, evaluation, safety, and limitations for generative AI applications.', 'DAIR.AI', 'https://www.promptingguide.ai/', 'Intermediate', 'tutorial', array['Artificial Intelligence', 'Generative AI', 'LLM', 'Prompt Engineering'], array['Structure effective prompts', 'Compare prompt strategies', 'Evaluate model limitations']),
        ('machine-learning', 'Machine Learning Crash Course', 'Learn supervised learning, regression, classification, embeddings, training, evaluation, and responsible ML concepts.', 'Google', 'https://developers.google.com/machine-learning/crash-course', 'Beginner', 'course', array['Machine Learning', 'Python', 'Data Science'], array['Build baseline models', 'Evaluate with appropriate metrics', 'Detect overfitting']),
        ('machine-learning', 'Introduction to Statistical Learning', 'Study linear and non-linear models, resampling, tree methods, support vector machines, and unsupervised learning.', 'Stanford University', 'https://www.statlearning.com/', 'Intermediate', 'course', array['Machine Learning', 'Statistics', 'Python', 'R'], array['Compare predictive models', 'Use resampling for validation', 'Explain bias-variance trade-offs']),
        ('machine-learning', 'PyTorch Tutorials', 'Learn tensors, autograd, neural networks, training loops, datasets, and model deployment concepts.', 'PyTorch', 'https://pytorch.org/tutorials/', 'Intermediate', 'tutorial', array['Machine Learning', 'Deep Learning', 'PyTorch', 'Python'], array['Create neural-network layers', 'Train a model with autograd', 'Evaluate model performance']),
        ('machine-learning', 'TensorFlow Tutorials', 'Build and train deep-learning models with TensorFlow APIs, datasets, preprocessing, and evaluation tools.', 'TensorFlow', 'https://www.tensorflow.org/tutorials', 'Intermediate', 'tutorial', array['Machine Learning', 'Deep Learning', 'TensorFlow', 'Python'], array['Prepare training data', 'Build neural networks', 'Export and evaluate trained models']),
        ('machine-learning', 'Fast.ai Practical Deep Learning', 'Learn practical deep learning through coding-oriented lessons about vision, NLP, tabular data, and deployment.', 'fast.ai', 'https://course.fast.ai/', 'Intermediate', 'course', array['Machine Learning', 'Deep Learning', 'Python'], array['Fine-tune pretrained models', 'Train models for common tasks', 'Evaluate and deploy predictions'])
) as seed(
    category_slug,
    title,
    description,
    provider,
    resource_url,
    difficulty,
    resource_type,
    skill_tags,
    objectives
)
where not exists (
    select 1
    from public.learning_resources existing
    where existing.resource_url = seed.resource_url
);

notify pgrst, 'reload schema';
